class Solution { public: int maximumProduct(vector<int>& nums){int first=INT_MIN,second=INT_MIN,third=INT_MIN,low1=INT_MAX,low2=INT_MAX;for(int value:nums){if(value>=first){third=second;second=first;first=value;}else if(value>=second){third=second;second=value;}else if(value>third)third=value;if(value<=low1){low2=low1;low1=value;}else if(value<low2)low2=value;}return max(1LL*first*second*third,1LL*first*low1*low2);} };
